#pragma once

#include <string>
#include <sstream>
#include <stdexcept>
#include <vector>
#include <list>
#include <set>
#include <unordered_set>
#include <map>
#include <unordered_map>
#include <yaml-cpp/yaml.h>
#include <fmt/format.h>

namespace ws::cfg {

// Forward declarations
class VarBase;

template<typename T, typename FromStr = VarConverter<std::string, T>, typename ToStr = VarConverter<T, std::string>>
class Var;

// VarConverter template class

template<typename From, typename To>
struct VarConverter {
    static To Convert(const From& from) {
        return static_cast<To>(from);
    }
};

// Specialization for string to primitive conversions
template<typename T>
struct VarConverter<std::string, T> {
    static T Convert(const std::string& str) {
        try {
            std::istringstream iss(str);
            T value;
            if (!(iss >> value)) {
                throw std::invalid_argument(fmt::format("Failed to convert string '{}' to type {}", str, typeid(T).name()));
            }
            return value;
        } catch (const std::exception& e) {
            throw std::invalid_argument(fmt::format("Conversion error: {}", e.what()));
        }
    }
};

// Specialization for primitive to string conversions
template<typename T>
struct VarConverter<T, std::string> {
    static std::string Convert(const T& value) {
        return std::to_string(value);
    }
};

// Specialization for string to string conversion
template<>
struct VarConverter<std::string, std::string> {
    static std::string Convert(const std::string& str) {
        return str;
    }
};

// Specializations for collection types
template<typename T>
struct VarConverter<std::string, std::vector<T>> {
    static std::vector<T> Convert(const std::string& yamlStr) {
        try {
            YAML::Node node = YAML::Load(yamlStr);
            if (!node.IsSequence()) {
                throw std::invalid_argument("Expected sequence for vector conversion");
            }
            std::vector<T> result;
            for (const auto& item : node) {
                result.push_back(VarConverter<std::string, T>::Convert(item.as<std::string>()));
            }
            return result;
        } catch (const std::exception& e) {
            throw std::invalid_argument(fmt::format("Vector conversion error: {}", e.what()));
        }
    }
};

template<typename T>
struct VarConverter<std::vector<T>, std::string> {
    static std::string Convert(const std::vector<T>& vec) {
        YAML::Node node;
        for (const auto& item : vec) {
            node.push_back(VarConverter<T, std::string>::Convert(item));
        }
        return YAML::Dump(node);
    }
};

// Similar specializations would be added for list, set, unordered_set, map, and unordered_map types

// VarBase abstract class
class VarBase {
public:
    virtual ~VarBase() = default;

    virtual std::string Name() const = 0;
    virtual std::string Description() const = 0;
    virtual std::string ToString() const = 0;
    virtual void FromString(const std::string& str) = 0;
};

// Var template class
template<typename T, typename FromStr, typename ToStr>
class Var : public VarBase {
public:
    using Listener = std::function<void(const T& oldVal, const T& newVal)>;

    explicit Var(std::string name, std::string description = "")
        : m_name(std::move(name)), m_description(std::move(description)) {}

    std::string Name() const override {
        return m_name;
    }

    std::string Description() const override {
        return m_description;
    }

    T GetValue() const {
        std::shared_lock lock(m_mutex);
        return m_value;
    }

    void SetValue(const T& newVal) {
        std::unique_lock lock(m_mutex);
        if (m_value == newVal) return;

        const T oldVal = m_value;
        m_value = newVal;

        for (const auto& listener : m_listeners) {
            try {
                listener(oldVal, newVal);
            } catch (const std::exception& e) {
                std::cerr << "Listener exception: " << e.what() << '\n';
            }
        }
    }

    uint64_t AddListener(Listener listener) {
        std::unique_lock lock(m_mutex);
        uint64_t key = m_nextKey++;
        m_listeners[key] = std::move(listener);
        return key;
    }

    void RemoveListener(uint64_t key) {
        std::unique_lock lock(m_mutex);
        m_listeners.erase(key);
    }

    std::string ToString() const override {
        std::shared_lock lock(m_mutex);
        return ToStr::Convert(m_value);
    }

    void FromString(const std::string& str) override {
        std::unique_lock lock(m_mutex);
        m_value = FromStr::Convert(str);
    }

private:
    mutable std::shared_mutex m_mutex;
    T m_value{};
    std::string m_name;
    std::string m_description;
    uint64_t m_nextKey = 1;
    std::unordered_map<uint64_t, Listener> m_listeners;
};

// Config class
class Config {
public:
    template<typename T>
    std::shared_ptr<Var<T>> Lookup(const std::string& name) {
        std::unique_lock lock(m_mutex);
        auto it = m_vars.find(name);
        if (it == m_vars.end()) {
            throw std::invalid_argument(fmt::format("Variable '{}' not found", name));
        }
        return std::static_pointer_cast<Var<T>>(it->second);
    }

    template<typename T>
    std::shared_ptr<Var<T>> Lookup(const std::string& name, const T& default_val) {
        std::unique_lock lock(m_mutex);
        auto it = m_vars.find(name);
        if (it == m_vars.end()) {
            auto var = std::make_shared<Var<T>>(name);
            var->SetValue(default_val);
            m_vars[name] = var;
            return var;
        }
        return std::static_pointer_cast<Var<T>>(it->second);
    }

    void LoadYaml(const YAML::Node& node) {
        std::unique_lock lock(m_mutex);
        ExtractMembers(node, "", *this);
    }

    template<typename Visitor>
    void Visit(Visitor visitor) {
        std::shared_lock lock(m_mutex);
        for (const auto& [name, var] : m_vars) {
            visitor(name, var);
        }
    }

private:
    mutable std::shared_mutex m_mutex;
    std::unordered_map<std::string, std::shared_ptr<VarBase>> m_vars;

    static void ExtractMembers(const YAML::Node& node, const std::string& prefix, Config& config) {
        if (node.IsMap()) {
            for (const auto& kv : node) {
                std::string newPrefix = prefix.empty() ? kv.first.as<std::string>() : prefix + "." + kv.first.as<std::string>();
                ExtractMembers(kv.second, newPrefix, config);
            }
        } else if (node.IsScalar()) {
            auto var = std::make_shared<Var<std::string>>(prefix);
            var->SetValue(node.as<std::string>());
            config.m_vars[prefix] = var;
        }
    }
};

// Root configuration singleton
inline std::shared_ptr<Config> RootConfig() {
    static std::shared_ptr<Config> instance = std::make_shared<Config>();
    return instance;
}

} // namespace ws::cfg

